#!/usr/bin/env node
/**
 * Ships the customer app's catalogue pictures inside the app instead of
 * fetching them from the website, so Explore services, All services and the
 * bundled banners show real photos instantly, offline, and whether or not the
 * website has been deployed with them.
 *
 *   assets/web/{areas,services,services/pet,services/helping,banners}
 *     →  apps/customer/src/lib/bundledArt.generated.ts
 *
 * The map is keyed by the website path the shared logic already returns
 * ("/areas/vehicles.jpg"), so serviceArt.js and homepageContent.js stay as
 * they are; anything not bundled still loads from the website.
 *
 * After adding or removing a picture in one of those folders:
 *   npm run sync:art   (from mobile/)      check:  npm run check:art
 */
const fs = require('fs');
const path = require('path');

const webRoot = path.resolve(__dirname, '../../assets/web');
const outFile = path.resolve(__dirname, '../apps/customer/src/lib/bundledArt.generated.ts');
const FOLDERS = ['areas', 'services', 'services/pet', 'services/helping', 'banners'];
const IMAGE = /\.(jpe?g|png|webp)$/i;

const entries = [];
for (const folder of FOLDERS) {
  const dir = path.join(webRoot, folder);
  if (!fs.existsSync(dir)) continue;
  for (const file of fs.readdirSync(dir).filter((f) => IMAGE.test(f)).sort()) {
    const webPath = `/${folder}/${file}`;
    const rel = path.relative(path.dirname(outFile), path.join(dir, file)).split(path.sep).join('/');
    entries.push(`  '${webPath}': require('${rel}'),`);
  }
}

const out = `/**
 * GENERATED by mobile/tools/sync-bundled-art.js from assets/web. Do not edit:
 * change the pictures there, then run \`npm run sync:art\` from mobile/.
 */
/* eslint-disable */
import type { ImageSourcePropType } from 'react-native';

export const BUNDLED_ART: Record<string, ImageSourcePropType> = {
${entries.join('\n')}
};
`;

if (process.argv.includes('--check')) {
  const current = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf8') : '';
  if (current !== out) {
    console.error('Bundled art is out of date with assets/web. Run: npm run sync:art (from mobile/)');
    process.exit(1);
  }
  console.log(`Bundled art in sync: ${entries.length} pictures.`);
} else {
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  fs.writeFileSync(outFile, out);
  console.log(`Wrote ${path.relative(process.cwd(), outFile)}: ${entries.length} pictures.`);
}
